public class Main {
    static int hitung(int n) {
        if (n <= 1) {
            return 1;
        }
        return n * hitung(n - 1);
    }

    public static void main(String[] args) {
        System.out.println(hitung(4));
    }
}

public class Main {
    static int kali(int a, int b) {
        return a * b;
    }

    static double kali(double a, double b) {
        return a * b;
    }

    public static void main(String[] args) {
        System.out.println(kali(2, 3));
        System.out.println(kali(2.0, 3.0));
    }
}

